import{_ as t,c as a,o,aj as n}from"./chunks/framework.CDhdelVI.js";const m=JSON.parse('{"title":"Fermentation & Proofing Planner","description":"How KitchenRatio estimates bulk fermentation and proofing time using yeast percentage and temperature.","frontmatter":{"title":"Fermentation & Proofing Planner","description":"How KitchenRatio estimates bulk fermentation and proofing time using yeast percentage and temperature.","head":[["meta",{"name":"description","content":"How KitchenRatio estimates bulk fermentation and proofing time using yeast percentage and temperature."}],["meta",{"property":"og:title","content":"Fermentation & Proofing Planner"}],["meta",{"property":"og:description","content":"How KitchenRatio estimates bulk fermentation and proofing time using yeast percentage and temperature."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/guides/fermentation-and-proofing-planner.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Fermentation & Proofing Planner"}],["meta",{"name":"twitter:description","content":"How KitchenRatio estimates bulk fermentation and proofing time using yeast percentage and temperature."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/guides/fermentation-and-proofing-planner.html"}]]},"headers":[],"relativePath":"guides/fermentation-and-proofing-planner.md","filePath":"guides/fermentation-and-proofing-planner.md"}'),r={name:"guides/fermentation-and-proofing-planner.md"};function i(l,e,s,p,d,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="fermentation-proofing-planner" tabindex="-1">Fermentation &amp; Proofing Planner <a class="header-anchor" href="#fermentation-proofing-planner" aria-label="Permalink to “Fermentation &amp; Proofing Planner”">​</a></h1><p>The calculator includes two timing helpers:</p><ul><li><strong>Bulk Fermentation</strong></li><li><strong>Proofing</strong></li></ul><p>These are yeast-aware, temperature-aware planning estimates. They are meant to speed up dialing in a process, not replace dough feel.</p><h2 id="where-it-shows-up" tabindex="-1">Where It Shows Up <a class="header-anchor" href="#where-it-shows-up" aria-label="Permalink to “Where It Shows Up”">​</a></h2><p>The planner cards appear when:</p><ul><li>Yeast is enabled</li><li>Yeast percentage is greater than 0</li></ul><p>If yeast is disabled or set to 0%, the cards are hidden.</p><h2 id="what-you-can-control" tabindex="-1">What You Can Control <a class="header-anchor" href="#what-you-can-control" aria-label="Permalink to “What You Can Control”">​</a></h2><p>Each stage (bulk and proofing) has the same controls:</p><ul><li><strong>Mode</strong>: <code>Room</code> or <code>Cold</code></li><li><strong>Use actual room or refrigerator temp</strong> toggle</li><li>Optional stage temperature input in °F</li></ul><p>If &quot;Use actual&quot; is off, the calculator uses stored defaults:</p><ul><li>Room: <strong>72°F</strong></li><li>Cold: <strong>38°F</strong></li></ul><p>When &quot;Use actual&quot; is on, allowed ranges are:</p><ul><li>Room temp: <strong>32-110°F</strong></li><li>Cold temp: <strong>32-60°F</strong></li></ul><h2 id="how-the-estimate-is-calculated" tabindex="-1">How the Estimate Is Calculated <a class="header-anchor" href="#how-the-estimate-is-calculated" aria-label="Permalink to “How the Estimate Is Calculated”">​</a></h2><p>The estimate uses:</p><ul><li>Active yeast percentage</li><li>Selected stage temperature</li><li>Stage type (<code>bulk</code> or <code>proofing</code>)</li></ul><p>Reference point:</p><ul><li><strong>1% yeast at 72°F</strong></li></ul><p>Stage base times:</p><ul><li><strong>Bulk base</strong>: 3.5 hours</li><li><strong>Proof base</strong>: 1.8 hours</li></ul><p>Temperature and yeast scale the base time, then the result is clamped:</p><ul><li>Bulk clamp: <strong>0.8 to 96 hours</strong></li><li>Proof clamp: <strong>0.4 to 72 hours</strong></li></ul><p>Displayed output is a range:</p><ul><li><strong>Low</strong> = estimate × 0.75</li><li><strong>High</strong> = estimate × 1.25</li></ul><h2 id="important-scope-notes" tabindex="-1">Important Scope Notes <a class="header-anchor" href="#important-scope-notes" aria-label="Permalink to “Important Scope Notes”">​</a></h2><p>The timing model currently responds directly to:</p><ul><li>Yeast %</li><li>Temperature</li></ul><p>It does <strong>not</strong> directly model:</p><ul><li>Hydration %</li><li>Flour strength/type</li><li>Salt %</li><li>Mixing intensity</li><li>Dough development or handling</li></ul><p>That is why the UI labels these as rough estimates.</p><h2 id="presets-and-defaults" tabindex="-1">Presets and Defaults <a class="header-anchor" href="#presets-and-defaults" aria-label="Permalink to “Presets and Defaults”">​</a></h2><p>Presets can preload bulk/proofing mode (room or cold).<br> Applying a preset resets stage panels to closed and disables &quot;Use actual temp&quot; until you opt in.</p><p>Reset behavior returns fermentation planning to:</p><ul><li>Bulk mode: <code>room</code></li><li>Proof mode: <code>room</code></li><li>Use actual temp: <code>off</code></li></ul><h2 id="practical-workflow" tabindex="-1">Practical Workflow <a class="header-anchor" href="#practical-workflow" aria-label="Permalink to “Practical Workflow”">​</a></h2><ol><li>Pick a preset or set your formula manually.</li><li>Set yeast % to match your schedule.</li><li>Choose room/cold mode for bulk and proof.</li><li>Turn on actual temp if your kitchen or fridge runs warmer/cooler than typical.</li><li>Use the estimated range as a starting target, then confirm by dough behavior.</li></ol><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/kitchenratio-calculator.html">KitchenRatio Calculator</a></li><li><a href="/guides/cold-fermentation.html">Cold Fermentation</a></li><li><a href="/guides/no-knead-vs-kneading.html">No-Knead vs Kneading</a></li><li><a href="/guides/hydration.html">Hydration</a></li></ul>',40)])])}const h=t(r,[["render",i]]);export{m as __pageData,h as default};
